function updateMoves(){G.selected=G.selected||0;const moves=[['Leaf Flick','BLOOM',7],['Cinder Pop','EMBER',8],['Bubble Jab','TIDE',7]];$('moves').innerHTML=moves.map((m,i)=>`<button class="move-btn ${G.selected===i?'selected':''}" data-move="${i}"><span class="move-icon">${TYPES[m[1]].icon}</span><span class="move-text"><span class="move-name">${m[0]}</span><br><span class="move-type">${m[1]}</span></span><span class="move-key">${i+1}</span></button>`).join('');document.querySelectorAll('.move-btn').forEach(b=>b.onclick=()=>{G.selected=+b.dataset.move;updateMoves();attack()})}
const sprites={};function sprite(type,player=false){let key=type+(player?'p':'');if(sprites[key])return sprites[key];let c=document.createElement('canvas');c.width=16;c.height=16;let q=c.getContext('2d');q.imageSmoothingEnabled=false;let pal=TYPES[type]||TYPES.BLOOM;const px=(x,y,w,h,col)=>{q.fillStyle=col;q.fillRect(x,y,w,h)};const dot=(x,y,col)=>px(x,y,1,1,col);const blob=(x,y,rx,ry,col)=>{q.fillStyle=col;q.beginPath();q.ellipse(x,y,rx,ry,0,0,Math.PI*2);q.fill()};
// Hand-built chunky silhouettes, each palette has its own little wild shape.
if(type==='BLOOM'){blob(8,9,5.6,4.7,pal.dark);blob(8,8,4.8,4.3,pal.color);px(4,4,2,4,pal.dark);px(4,3,2,2,pal.color);px(10,3,2,5,pal.dark);px(11,2,2,3,pal.light);px(2,10,3,2,pal.dark);px(11,11,3,2,pal.dark);px(5,12,2,2,pal.dark);px(10,12,2,2,pal.dark);px(7,4,1,2,pal.accent)}else if(type==='EMBER'){blob(8,9,5.5,4.5,pal.dark);blob(8,8,4.5,4,pal.color);px(3,5,3,4,pal.dark);px(4,4,2,3,pal.color);px(10,4,3,5,pal.dark);px(11,3,2,3,pal.color);px(2,8,3,2,pal.accent);px(12,10,3,2,pal.dark);px(5,12,2,2,pal.dark);px(10,12,2,2,pal.dark);px(7,3,2,2,pal.light)}else if(type==='TIDE'){blob(8,9,5.3,4.7,pal.dark);blob(8,8,4.6,4,pal.color);px(2,7,3,2,pal.dark);px(1,6,2,2,pal.light);px(11,5,3,2,pal.dark);px(12,4,2,2,pal.light);px(5,12,2,2,pal.dark);px(10,12,2,2,pal.dark);px(7,4,2,2,pal.accent);px(8,3,1,2,pal.light)}else{blob(8,9,5.2,4.6,pal.dark);blob(8,8,4.4,4,pal.color);px(3,3,3,5,pal.dark);px(4,2,2,4,pal.light);px(10,3,3,5,pal.dark);px(11,2,2,4,pal.light);px(2,9,3,2,pal.dark);px(12,10,2,2,pal.dark);px(5,12,2,2,pal.dark);px(10,12,2,2,pal.dark);px(7,4,2,2,pal.accent)}
// face, feet, and signature pixel glint
px(6,7,1,2,'#263b3b');px(10,7,1,2,'#263b3b');px(6,7,1,1,'#fff6ce');px(10,7,1,1,'#fff6ce');px(7,10,2,1,pal.dark);px(5,14,2,1,'#334543');px(10,14,2,1,'#334543');if(player){px(6,5,5,2,'#e5bf76');px(7,4,3,2,'#344e56');px(7,5,3,1,'#f3d288')}
sprites[key]=c;return c}
function project(x,y){const tw=Math.min(cw*.091,ch*.145),th=tw*.5;return{x:(cw/2)+((x-y)*tw/2),y:ch*.50+((x+y-8)*th/2),tw,th}}
function diamond(x,y,tw,th,fill,stroke){ctx.beginPath();ctx.moveTo(x,y-th/2);ctx.lineTo(x+tw/2,y);ctx.lineTo(x,y+th/2);ctx.lineTo(x-tw/2,y);ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
function drawProp(o){let p=project(o.x,o.y),s=p.tw/44;ctx.save();ctx.translate(p.x,p.y);if(o.type==='fern'){ctx.fillStyle='#567c5b';ctx.beginPath();ctx.ellipse(0,0,10*s,4*s,0,0,Math.PI*2);ctx.fill();for(let i=0;i<5;i++){ctx.save();ctx.rotate((i-2)*.34);ctx.fillStyle=['#639568','#79a77a','#426e57'][((i+o.variant)%3)];ctx.beginPath();ctx.ellipse(0,-8*s,3*s,9*s,0,0,Math.PI*2);ctx.fill();ctx.restore()}ctx.fillStyle='#bdd391';ctx.fillRect(-1*s,-14*s,2*s,4*s)}else{ctx.fillStyle='#78917f';ctx.beginPath();ctx.moveTo(-9*s,0);ctx.lineTo(-7*s,-8*s);ctx.lineTo(-2*s,-12*s);ctx.lineTo(5*s,-9*s);ctx.lineTo(9*s,0);ctx.closePath();ctx.fill();ctx.fillStyle='#a5b59a';ctx.fillRect(-3*s,-8*s,3*s,2*s)}ctx.restore()}
function draw(){if(!G||!cw)return;ctx.clearRect(0,0,cw,ch);let g=ctx.createLinearGradient(0,0,0,ch);g.addColorStop(0,'#d7e6d3');g.addColorStop(1,'#a8c7ae');ctx.fillStyle=g;ctx.fillRect(0,0,cw,ch);let tw=Math.min(cw*.091,ch*.145),th=tw*.5;
// soft luminous clearings in the wild
for(let i=0;i<7;i++){let x=cw*(.08+i*.15),y=ch*(.2+(i%3)*.2);let rg=ctx.createRadialGradient(x,y,1,x,y,cw*.18);rg.addColorStop(0,'#edf0d255');rg.addColorStop(1,'#edf0d200');ctx.fillStyle=rg;ctx.fillRect(x-cw*.2,y-cw*.2,cw*.4,cw*.4)}
for(let y=0;y<9;y++)for(let x=0;x<11;x++){let p=project(x,y);let alt=(x*7+y*13+G.floor)%5;diamond(p.x,p.y,tw,th,['#bad2b2','#c1d9b8','#b4cdaa','#c5dabb','#b9d1b3'][alt],'#9fbda555');if((x*11+y*5)%8===0){ctx.fillStyle='#7fa77d88';ctx.fillRect(p.x+((x+y)%3-1)*3,p.y,2,1)}}
// exit tile
let ex=project(G.exit.x,G.exit.y);diamond(ex.x,ex.y,tw*.8,th*.8,G.enemies.some(e=>e.alive)?'#adc4a5':'#e9d39b','#f3e7b4');if(!G.enemies.some(e=>e.alive)){ctx.fillStyle='#f8eab9';ctx.font=`${tw*.35}px sans-serif`;ctx.textAlign='center';ctx.fillText('✦',ex.x,ex.y+tw*.12)}
let list=[];G.obstacles.forEach(o=>list.push({z:o.x+o.y,kind:'prop',o}));G.enemies.filter(e=>e.alive).forEach(e=>list.push({z:e.x+e.y,kind:'enemy',o:e}));list.push({z:G.x+G.y,kind:'player',o:{x:G.x,y:G.y}});list.sort((a,b)=>a.z-b.z);
for(let item of list){let o=item.o,p=project(o.x,o.y),s=tw/45;if(item.kind==='prop'){drawProp(o);continue}ctx.save();ctx.fillStyle='#314f3d35';ctx.beginPath();ctx.ellipse(p.x,p.y+2*s,11*s,4*s,0,0,Math.PI*2);ctx.fill();if(item.kind==='enemy'){if(G.battle?.enemy===o)ctx.globalAlpha=.72;let bob=Math.sin(Date.now()/330+o.x)*1.5*s;ctx.imageSmoothingEnabled=false;ctx.drawImage(sprite(o.type),p.x-15*s,p.y-31*s+bob,30*s,30*s);if(o.boss){ctx.fillStyle='#f8e4a4';ctx.font=`bold ${9*s}px sans-serif`;ctx.textAlign='center';ctx.fillText('✦',p.x,p.y-33*s)}}else{let bob=Math.sin(Date.now()/250)*.8*s;ctx.imageSmoothingEnabled=false;ctx.drawImage(sprite('BLOOM',true),p.x-17*s,p.y-34*s+bob,34*s,34*s);ctx.fillStyle='#f6dc97';ctx.beginPath();ctx.arc(p.x,p.y-38*s+bob,2*s,0,Math.PI*2);ctx.fill()}ctx.restore()}
if(G.shake>0){G.shake*=.85}requestAnimationFrame(draw)}

