if(G.shake>0){G.shake*=.85}}
function nearestEnemy(max=2){return G.enemies.filter(e=>e.alive).map(e=>({e,d:Math.abs(e.x-G.x)+Math.abs(e.y-G.y)})).filter(v=>v.d<=max).sort((a,b)=>a.d-b.d)[0]?.e}
function beginBattle(enemy){if(G.battle||!enemy)return;G.battle={enemy};$('encounter').classList.add('open');$('enemyName').textContent=enemy.name;$('enemyLevel').textContent=`WILD${enemy.boss?' · BOSS':''} · LV ${enemy.level}`;$('enemyHpText').textContent=`${enemy.hp} / ${enemy.max}`;$('enemyHp').style.width='100%';$('enemySprite').getContext('2d').clearRect(0,0,64,64);let ec=$('enemySprite').getContext('2d');ec.imageSmoothingEnabled=false;ec.drawImage(sprite(enemy.type),8,5,48,48);$('battleMessage').textContent=`A wild ${enemy.name} steps into your path!`;$('battleActions').innerHTML=[['Leaf Flick','BLOOM','✿'],['Cinder Pop','EMBER','✹'],['Bubble Jab','TIDE','◈']].map((m,i)=>`<button class="battle-move" data-b="${i}">${m[2]} ${m[0]}<small>${m[1]}</small></button>`).join('');document.querySelectorAll('.battle-move').forEach(b=>b.onclick=()=>{G.selected=+b.dataset.b;attack()});log(`A wild ${enemy.name} appeared. Choose a technique!`)}
function closeBattle(){if(!G.battle)return;$('encounter').classList.remove('open');G.battle=null;draw()}
function attack(){if(!G.active||G.ended)return;let enemy=G.battle?.enemy||nearestEnemy(3);if(!enemy){note('No wild creature close enough.');return}if(!G.battle)beginBattle(enemy);let m=MOVES[[0,3,6][G.selected||0]],type=m[1],base=m[2];let bonus=enemy.type==='EMBER'&&type==='TIDE'||enemy.type==='TIDE'&&type==='BLOOM'||enemy.type==='BLOOM'&&type==='EMBER'||enemy.type==='DUSK'&&type==='BLOOM';let resist=enemy.type==='BLOOM'&&type==='TIDE'||enemy.type==='EMBER'&&type==='BLOOM'||enemy.type==='TIDE'&&type==='EMBER';let dmg=Math.max(2,base+Math.floor(G.r()*5)+G.party.length-(resist?3:0)+(bonus?4:0));enemy.hp=Math.max(0,enemy.hp-dmg);$('enemyHpText').textContent=`${enemy.hp} / ${enemy.max}`;$('enemyHp').style.width=`${enemy.hp/enemy.max*100}%`;$('battleMessage').textContent=`${m[0]} hits for ${dmg} damage${bonus?' — a bright advantage!':''}`;log(`${m[0]} dealt ${dmg} damage.`);draw();if(enemy.hp<=0){setTimeout(()=>winBattle(enemy),360);return}setTimeout(enemyTurn,360)}
function enemyTurn(){if(!G.battle||G.ended)return;let e=G.battle.enemy,damage=Math.max(2,Math.floor((3+e.level*1.35+G.r()*4)*(e.boss?1.35:1))-(G.party.length?Math.min(3,Math.floor(G.party.length/2)):0));G.player.hp=Math.max(0,G.player.hp-damage);$('battleMessage').textContent=`${e.name} lashes out! You lose ${damage} vitality.`;log(`${e.name} struck back for ${damage}.`);updateUI();if(G.player.hp<=0){setTimeout(()=>finishRun(false),500)}}
function winBattle(e){if(!G.battle)return;e.alive=false;G.wins++;let xp=8+e.level*6+(e.boss?20:0);G.player.xp+=xp;levelUp();if(G.party.length<5){G.party.push({name:e.name,type:e.type,emoji:e.emoji,level:e.level});$('battleMessage').textContent=`${e.name} settles in beside you — caught automatically! +${xp} XP`;$('catchFlash').classList.remove('show');void $('catchFlash').offsetWidth;$('catchFlash').classList.add('show')}else{G.shards++;$('battleMessage').textContent=`Your team is full. ${e.name} leaves a shard instead. +${xp} XP`}
log(`${e.name} joined your team! +${xp} XP.`);updateUI();let boss=e.boss;setTimeout(()=>{closeBattle();if(boss){finishRun(true);return}if(!G.enemies.some(x=>x.alive)){note('The clearing is quiet. Find the golden exit tile!');log('Every wild in this clearing has joined you. Seek the exit.')}},1000)}
function enemyAt(x,y){return G.enemies.find(e=>e.alive&&e.x===x&&e.y===y)}
function move(dx,dy){if(!G.active||G.ended||G.battle)return;let x=G.x+dx,y=G.y+dy;if(x<0||x>10||y<0||y>8)return;let e=enemyAt(x,y);if(e){beginBattle(e);return}G.x=x;G.y=y;G.step++;if(G.step%7===0&&G.player.hp<G.player.max){G.player.hp=Math.min(G.player.max,G.player.hp+1);updateUI()}if(x===G.exit.x&&y===G.exit.y){if(G.enemies.some(e=>e.alive)){note('Defeat every wild creature before the exit opens.')}else if(G.floor===5){finishRun(true)}else nextFloor()}draw()}
function nextFloor(){G.floor++;G.player.hp=Math.min(G.player.max,G.player.hp+8);generateFloor();$('depth').textContent=`FLOOR ${String(G.floor).padStart(2,'0')} / 05`;log(`Floor ${G.floor}: ${ZONES[G.floor-1]}. A warm light restores 8 vitality.`);note(`Floor ${G.floor} — ${ZONES[G.floor-1]}`);updateUI();draw()}
function finishRun(won){G.ended=true;$('endGlyph').textContent=won?'🌟':'🌘';$('endTitle').textContent=won?'SHARDSONG!':'THE WILD GOES QUIET';$('endText').textContent=won?`You crossed the wilds and befriended ${G.party.length} creatures. Your team made it home together.`:`You reached floor ${G.floor} with ${G.party.length} creature${G.party.length===1?'':'s'} by your side. The wilds will remember you.`;$('endOverlay').classList.add('show');closeBattle()}
function action(){if(G.battle){attack();return}let e=nearestEnemy(3);if(e){beginBattle(e);return}if(G.x===G.exit.x&&G.y===G.exit.y){if(G.enemies.some(e=>e.alive))note('Defeat every wild creature before the exit opens.');else if(G.floor===5)finishRun(true);else nextFloor()}else note('Wander closer to a wild creature to challenge it.')}

