import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const captures = require('/home/runner/work/_temp/omgithub-runtime/scripts/wip-screenshots.cjs');
captures.instrument({ chromium });
const config = JSON.parse(readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json', 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync('/home/runner/.local/share/omgithub-playwright/display', 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
mkdirSync('/tmp/opencode/wildshard-validation', { recursive: true });
for (const [name, width, height] of [['desktop', 1440, 900], ['mobile', 390, 844]]) {
  const page = await browser.newPage({ viewport: { width, height } });
  page.setDefaultTimeout(10000);
  page.on('pageerror', e => console.log(name, 'PAGEERROR', e.message));
  await page.goto('http://127.0.0.1:3000', { waitUntil: 'load' });
  await page.waitForFunction(() => document.fonts.status === 'loaded');
  await page.locator('#begin').evaluate(el => el.click());
  const first = await page.evaluate(() => ({ active: window.eval('G.active'), party: window.eval('G.party.length'), enemies: window.eval('G.enemies.length') }));
  if (!first.active || first.party !== 1) throw Error(`${name}: run did not start ${JSON.stringify(first)}`);
  await page.evaluate(() => { const g = window.eval('G'); window.eval('beginBattle(G.enemies.find(e => e.alive))'); });
  await page.waitForTimeout(500);
  const battle = await page.evaluate(() => ({ open: document.querySelector('#encounter').classList.contains('open'), gl: !!document.querySelector('#battle3d').getContext('webgl'), moves: document.querySelectorAll('.battle-move').length }));
  await page.screenshot({ path: `/tmp/opencode/wildshard-validation/${name}-battle.png` });
  if (!battle.open || !battle.moves) throw Error(`${name}: battle UI failed ${JSON.stringify(battle)}`);
  await page.evaluate(() => { window.eval('G.battle.enemy.hp = 1'); });
  await page.locator('.battle-move').first().click();
  await page.waitForTimeout(500);
  const damage = await page.evaluate(() => ({ hp: window.eval('G.battle.enemy.hp'), allyHp: window.eval('G.party[0].hp') }));
  await page.waitForTimeout(600);
  const recruited = await page.evaluate(() => ({ party: window.eval('G.party.length'), wins: window.eval('G.wins'), active: window.eval('G.activeIndex'), battle: !!window.eval('G.battle') }));
  if (recruited.party !== 2 || recruited.wins !== 1) throw Error(`${name}: recruitment failed ${JSON.stringify({damage,recruited})}`);
  await page.evaluate(() => { const g = window.eval('G'); g.party[g.activeIndex].hp = 1; window.eval('enemyTurn()'); });
  const fallback = await page.evaluate(() => ({ active: window.eval('G.activeIndex'), activeHp: window.eval('G.party[G.activeIndex].hp'), ally: document.querySelector('#allyName').textContent }));
  if (fallback.active !== 1 || fallback.activeHp <= 0) throw Error(`${name}: knockout fallback failed ${JSON.stringify(fallback)}`);
  const mobileControls = await page.locator('.mobile-controls').evaluate(el => getComputedStyle(el).display !== 'none');
  console.log(name, JSON.stringify({ first, battle, damage, recruited, fallback, mobileControls }));
  await page.screenshot({ path: `/tmp/opencode/wildshard-validation/${name}-recruited.png` });
  await page.close();
}
await browser.close();

